const BumpAllocator = struct {
    buf: []u8,
    offset: usize,

    fn alloc(ctx: *anyopaque, len: usize, ptr_align: u8, _: usize) ?[*]u8 {
        const self: *BumpAllocator = @ptrCast(@alignCast(ctx));
        const align_val = @as(usize, 1) << @intCast(ptr_align);
        const aligned = std.mem.alignForward(usize, self.offset, align_val);
        if (aligned + len > self.buf.len) return null;
        self.offset = aligned + len;
        return self.buf.ptr + aligned;
    }

    fn allocator(self: *BumpAllocator) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &vtable };
    }

    const vtable = std.mem.Allocator.VTable{
        .alloc = alloc,
        .resize = noResize,
        .remap = noRemap,
        .free = noFree,
    };
};

